/* SIDONIA · La marca en el panel: el logo (arriba) y la «O» (icono de la pestaña del navegador). Imágenes pequeñas,
 * metidas en la página para no depender de nada más. Salen de assets/sidonia-app-logo.png y sidonia-app-isotipo.png del tema. */
export const LOGO = 'data:image/png;base64,';
export const ISOTIPO = 'data:image/png;base64,';

/* ---------------------------------------------------------------------------- En la pantalla de inicio */
// La «O» en blanco sobre el fondo del panel, para el icono de la pantalla de inicio (iPhone, Android)
const ICONOS = {
  180: '',
  192: '',
  512: ''
};

/**
 * Lo que necesita el móvil para añadir el panel a la pantalla de inicio (sin contraseña: no enseña nada):
 *   /admin?recurso=manifest   → el manifiesto (nombre, colores, iconos; se abre a pantalla completa)
 *   /admin?recurso=icono-180|192|512 → el icono
 */
export function recursoPanel(nombre) {
  const cache = { 'Cache-Control': 'public, max-age=86400' };
  if (nombre === 'manifest') {
    return { status: 200, headers: { 'Content-Type': 'application/manifest+json; charset=utf-8', ...cache }, body: JSON.stringify({
      name: 'Sidonia · Panel', short_name: 'Sidonia', description: 'El panel del equipo de Sidonia: ventas, anuncios, clientes y estadísticas.',
      start_url: '/admin', scope: '/', display: 'standalone', orientation: 'portrait', background_color: '#0b120f', theme_color: '#0b120f', lang: 'es',
      icons: [180, 192, 512].map((t) => ({ src: `/admin?recurso=icono-${t}`, sizes: `${t}x${t}`, type: 'image/png', purpose: 'any' }))
        .concat({ src: '/admin?recurso=icono-512', sizes: '512x512', type: 'image/png', purpose: 'maskable' })
    }) };
  }
  const t = (String(nombre || '').match(/^icono-(180|192|512)$/) || [])[1];
  if (t) return { status: 200, headers: { 'Content-Type': 'image/png', ...cache }, body: Buffer.from(ICONOS[t], 'base64') };
  return { status: 404, headers: { 'Content-Type': 'text/plain; charset=utf-8' }, body: 'No existe' };
}

/**
 * Lo que va en el <head> de cada página del panel: las tipografías de la web (Carlito para los títulos, Inter para el
 * texto), la «O» de icono y el tema (oscuro por defecto; el botón de arriba lo cambia y se recuerda en este navegador).
 */
export const FAVICON = `<link rel="icon" type="image/png" href="${ISOTIPO}">
<link rel="manifest" href="/admin?recurso=manifest"><link rel="apple-touch-icon" href="/admin?recurso=icono-180">
<meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-title" content="Sidonia"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
<meta name="theme-color" content="#0b120f">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Carlito:wght@400;700&family=Inter:wght@400;500;600;700;800&display=swap">
<script>(() => { let t = 'oscuro'; try { t = localStorage.getItem('sidonia-panel-tema') || 'oscuro'; } catch (e) {} document.documentElement.dataset.tema = t; })();</script>`;

const SOL = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="4.5"/><path d="M12 2v2.5M12 19.5V22M4.2 4.2l1.8 1.8M18 18l1.8 1.8M2 12h2.5M19.5 12H22M4.2 19.8 6 18M18 6l1.8-1.8"/></svg>';
const LUNA = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 14.5A8.5 8.5 0 1 1 9.5 4a7 7 0 0 0 10.5 10.5Z"/></svg>';

/** La barra de arriba: el logo de Sidonia, «Panel» y el botón de oscuro / claro */
export const CABECERA = `<header class="cabeza">
  <a class="cabeza__marca" href="?" title="Ir a Ventas"><img class="cabeza__logo" src="${LOGO}" alt="Sidonia" width="130" height="27"><span>Panel</span></a>
  <button type="button" class="cabeza__tema" aria-label="Cambiar entre oscuro y claro" title="Oscuro / claro"
    onclick="const h=document.documentElement;h.dataset.tema=h.dataset.tema==='claro'?'oscuro':'claro';try{localStorage.setItem('sidonia-panel-tema',h.dataset.tema)}catch(e){}">
    <span class="cabeza__sol">${SOL}</span><span class="cabeza__luna">${LUNA}</span></button>
</header>`;

/**
 * El estilo de todo el panel. Oscuro (por defecto) o claro con html[data-tema]. Verde para lo que va bien (ventas,
 * subidas), rojo para lo que baja o falta, amarillo para lo pendiente. Números con cifras del mismo ancho (tabulares).
 */
export const ESTILO_PANEL = `
  :root, [data-tema="oscuro"] {
    color-scheme: dark;
    --fondo: #0b120f; --fondo-2: #0f1814; --caja: #141f1a; --caja-2: #1a2721; --caja-3: #22322a;
    --linea: rgba(255,255,255,.07); --linea-2: rgba(255,255,255,.14);
    --texto: #eef4f0; --suave: rgba(238,244,240,.62); --flojo: rgba(238,244,240,.4);
    --verde: #2bd47d; --verde-fondo: rgba(43,212,125,.14); --verde-tinta: #04150c;
    --rojo: #ff5f5f; --rojo-fondo: rgba(255,95,95,.14);
    --amarillo: #ffd23f; --amarillo-fondo: rgba(255,210,63,.14);
    --azul: #6cb4ff; --azul-fondo: rgba(108,180,255,.14);
    --lila: #c39bff; --lila-fondo: rgba(195,155,255,.14);
    --barra: #2bd47d; --barra-fondo: rgba(255,255,255,.07);
    --sombra: 0 1px 0 rgba(255,255,255,.03) inset, 0 8px 24px -16px rgba(0,0,0,.6);
    --logo: invert(1);
  }
  [data-tema="claro"] {
    color-scheme: light;
    --fondo: #f3f5f4; --fondo-2: #eaeeec; --caja: #ffffff; --caja-2: #f5f7f6; --caja-3: #eceff0;
    --linea: rgba(10,25,18,.08); --linea-2: rgba(10,25,18,.16);
    --texto: #0d1511; --suave: rgba(13,21,17,.62); --flojo: rgba(13,21,17,.42);
    --verde: #0b8f4d; --verde-fondo: rgba(11,143,77,.1); --verde-tinta: #ffffff;
    --rojo: #d23a2f; --rojo-fondo: rgba(210,58,47,.1);
    --amarillo: #a86b00; --amarillo-fondo: rgba(240,170,0,.15);
    --azul: #1f63c6; --azul-fondo: rgba(31,99,198,.1);
    --lila: #7a43c9; --lila-fondo: rgba(122,67,201,.1);
    --barra: #0b8f4d; --barra-fondo: rgba(10,25,18,.07);
    --sombra: 0 1px 2px rgba(10,25,18,.05), 0 8px 24px -18px rgba(10,25,18,.25);
    --logo: none;
  }
  * { box-sizing: border-box; }
  html { background: var(--fondo); color: var(--texto); font-family: Inter, system-ui, -apple-system, 'Segoe UI', sans-serif; font-size: 15px; -webkit-text-size-adjust: 100%; }
  body { max-width: 1240px; margin: 0 auto; padding: 0 20px 80px; background: var(--fondo); font-feature-settings: 'tnum' 1, 'cv11' 1; line-height: 1.45; }
  a { color: inherit; text-decoration-color: var(--linea-2); text-underline-offset: 3px; } a:hover { text-decoration-color: currentColor; }
  h1, h2, h3, th, .kpi span, nav a, .cabeza__marca span, .per a, .boton, button { font-family: Carlito, Inter, system-ui, sans-serif; }
  h2 { margin: 0 0 14px; font-size: 15px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--suave); }
  h2 small { font-weight: 400; text-transform: none; letter-spacing: 0; }

  /* Barra de arriba */
  .cabeza { position: sticky; top: 0; z-index: 20; display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 0 -20px 4px; padding: calc(14px + env(safe-area-inset-top)) max(20px, env(safe-area-inset-right)) 14px max(20px, env(safe-area-inset-left));
    background: color-mix(in srgb, var(--fondo) 86%, transparent); -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px); border-bottom: 1px solid var(--linea); }
  .cabeza__marca { display: flex; align-items: center; gap: 12px; text-decoration: none; }
  .cabeza__logo { display: block; width: auto; height: 24px; filter: var(--logo); }
  .cabeza__marca span { padding: 3px 8px; border-radius: 6px; background: var(--verde); color: var(--verde-tinta); font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; }
  .cabeza__tema { display: grid; place-items: center; width: 38px; height: 38px; padding: 0; border: 1px solid var(--linea-2); border-radius: 50%; background: var(--caja); color: var(--texto); cursor: pointer; }
  .cabeza .cabeza__tema { padding: 0; border-color: var(--linea-2); background: var(--caja); color: var(--texto) !important; border-radius: 50%; }
  [data-tema="claro"] .cabeza__sol, :root:not([data-tema="claro"]) .cabeza__luna { display: none; }

  /* Secciones y apartados */
  nav { display: flex; flex-wrap: nowrap; gap: 6px; margin: 16px 0; overflow-x: auto; scrollbar-width: none; -webkit-overflow-scrolling: touch; }
  nav::-webkit-scrollbar { display: none; }
  nav a { flex: none; display: inline-flex; align-items: center; gap: 6px; padding: 9px 16px; border: 1px solid var(--linea); border-radius: 10px; background: var(--caja); color: var(--suave); text-decoration: none; font-size: 15px; font-weight: 700; letter-spacing: .02em; white-space: nowrap; transition: background .15s, color .15s; }
  nav a:hover { color: var(--texto); background: var(--caja-2); }
  nav a.on { color: var(--texto); border-color: var(--linea-2); }
  nav.main a.on { background: var(--verde); border-color: var(--verde); color: var(--verde-tinta); }
  nav.sub { margin: -6px 0 18px; gap: 2px; padding: 3px; width: max-content; max-width: 100%; border-radius: 12px; background: var(--caja); border: 1px solid var(--linea); }
  nav.sub a { padding: 7px 13px; border: 0; border-radius: 9px; background: transparent; font-size: 14px; }
  nav.sub a.on { background: var(--caja-3); }
  nav .num { display: inline-block; min-width: 19px; padding: 0 6px; border-radius: 99px; background: var(--rojo); color: #fff; font-family: Inter, sans-serif; font-size: 11px; font-weight: 800; line-height: 19px; text-align: center; }

  /* Selector de periodo / filtros */
  .per { display: inline-flex; gap: 2px; padding: 3px; border-radius: 12px; background: var(--caja); border: 1px solid var(--linea); margin: 0 0 16px; max-width: 100%; overflow-x: auto; scrollbar-width: none; }
  .per a { flex: none; padding: 7px 13px; border-radius: 9px; color: var(--suave); text-decoration: none; font-size: 14px; font-weight: 700; white-space: nowrap; }
  .per a small { font-family: Inter, sans-serif; font-weight: 600; opacity: .6; margin-left: 2px; }
  .per a.on { background: var(--caja-3); color: var(--texto); }

  /* Números grandes */
  .kpis { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 10px; margin-bottom: 14px; }
  .kpi { container-type: inline-size; position: relative; display: flex; flex-direction: column; gap: 2px; min-width: 0; padding: 16px 16px 14px; border-radius: 16px; background: var(--caja); border: 1px solid var(--linea); box-shadow: var(--sombra); }
  .kpi b { order: 1; font-size: clamp(20px, 14.5cqi, 34px); font-weight: 800; letter-spacing: -.02em; line-height: 1.1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .kpi span { order: 0; font-size: 13px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--suave); }
  .kpi small { order: 2; margin-top: 4px; font-size: 12px; color: var(--flojo); line-height: 1.35; }
  .kpi em { order: 3; align-self: flex-start; margin-top: 8px; padding: 2px 7px; border-radius: 6px; font-style: normal; font-size: 12px; font-weight: 800; background: var(--caja-3); color: var(--suave); }
  .kpi em.sube { background: var(--verde-fondo); color: var(--verde); } .kpi em.sube::before { content: '▲ '; font-size: 9px; }
  .kpi em.baja { background: var(--rojo-fondo); color: var(--rojo); } .kpi em.baja::before { content: '▼ '; font-size: 9px; }

  /* Cajas */
  .card { padding: 18px 20px; border-radius: 16px; background: var(--caja); border: 1px solid var(--linea); box-shadow: var(--sombra); margin-bottom: 14px; min-width: 0; }
  .grid2 { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 320px), 1fr)); gap: 14px; margin-bottom: 14px; }
  .grid2 .card { margin: 0; }
  .cab { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; justify-content: space-between; }
  .cab h2 { margin: 0 0 4px; font-size: clamp(22px, 1rem + 1.4vw, 30px); letter-spacing: -.01em; text-transform: none; color: var(--texto); }
  .cab p { margin: 0; color: var(--suave); font-size: 14px; }

  /* Embudo */
  .embudo { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px; }
  .embudo div b { display: block; font-size: 28px; font-weight: 800; } .embudo div span { font-size: 13px; color: var(--suave); }
  .embudo i { font-style: normal; color: var(--verde); font-size: 22px; }
  .embudo p { flex-basis: 100%; margin: 6px 0 0; font-size: 14px; color: var(--suave); } .embudo p b { color: var(--verde); }

  /* Gráfica */
  .graf { width: 100%; height: auto; display: block; } .graf .g-bar { fill: var(--caja-3); } .graf .g-bar:hover { fill: var(--verde); }
  .graf .g-linea { stroke: var(--verde); } .graf .g-eje { stroke: var(--linea-2); } .graf text { fill: var(--flojo); font-family: Inter, sans-serif; }
  .ley { margin: 8px 0 0; font-size: 12px; color: var(--suave); display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
  .ley span { display: inline-block; width: 10px; height: 10px; border-radius: 3px; margin-left: 10px; } .c1 { background: var(--caja-3); } .c2 { background: var(--verde); }

  /* Barras */
  .bars { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
  .bars li { display: grid; grid-template-columns: minmax(110px, 190px) 1fr minmax(48px, auto); align-items: center; gap: 12px; font-size: 14px; }
  .bars .bl { min-width: 0; overflow-wrap: anywhere; } .bars .bl .sub { display: block; }
  .bb { height: 8px; border-radius: 99px; background: var(--barra-fondo); overflow: hidden; } .bb i { display: block; height: 100%; border-radius: 99px; background: var(--barra); }
  .bars b { text-align: right; font-weight: 800; white-space: nowrap; }
  ol.top { margin: 0; padding-left: 22px; display: grid; gap: 8px; font-size: 14px; } ol.top li::marker { color: var(--flojo); font-weight: 700; } ol.top li b { float: right; font-weight: 800; color: var(--verde); }

  .chips { display: flex; flex-wrap: wrap; gap: 6px; }
  .chips a { padding: 7px 12px; border-radius: 10px; background: var(--caja-2); border: 1px solid var(--linea); text-decoration: none; font-size: 14px; } .chips b { color: var(--verde); margin-left: 6px; font-weight: 800; }

  /* Tablas: en el móvil se deslizan de lado, con la primera columna fija */
  .tabla { overflow-x: auto; margin: 0 -20px; padding: 0 20px; -webkit-overflow-scrolling: touch; }
  .card .tabla { margin: 0 -20px; }
  table { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 14px; }
  th, td { padding: 11px 10px; border-bottom: 1px solid var(--linea); text-align: right; vertical-align: top; white-space: nowrap; }
  th:first-child, td:first-child { text-align: left; white-space: normal; min-width: 210px; }
  th { position: sticky; top: 0; font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--flojo); background: var(--caja); }
  tbody tr:last-child td { border-bottom: 0; }
  td.izq, th.izq { text-align: left; } td .sub, .sub { display: block; font-size: 12px; color: var(--flojo); font-weight: 400; }
  td b { font-weight: 700; }
  tr[data-q] { cursor: pointer; } tr[data-q]:hover td { background: var(--caja-2); }
  .si { color: var(--verde); font-weight: 800; }

  /* Etiquetas de estado */
  .pill, .temp { display: inline-block; padding: 3px 9px; border-radius: 7px; font-size: 12px; font-weight: 800; white-space: nowrap; background: var(--caja-3); color: var(--suave); }
  .pill.vendido { background: var(--verde-fondo); color: var(--verde); }
  .pill.en_venta { background: var(--azul-fondo); color: var(--azul); } .pill.reservado, .pill.pendiente { background: var(--amarillo-fondo); color: var(--amarillo); }
  .pill.retirado { background: var(--rojo-fondo); color: var(--rojo); }
  .temp.caliente { background: var(--rojo-fondo); color: var(--rojo); } .temp.templado { background: var(--amarillo-fondo); color: var(--amarillo); } .temp.frio { background: var(--azul-fondo); color: var(--azul); }

  /* Botones, buscadores y avisos */
  .barra, .filtros { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 0 0 14px; }
  input[type=search], .filtros input { flex: 1 1 220px; min-width: 0; padding: 10px 14px; border: 1px solid var(--linea-2); border-radius: 10px; background: var(--caja); color: var(--texto); font: inherit; font-size: 15px; }
  .boton, button { display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 10px 16px; border: 1px solid transparent; border-radius: 10px; background: var(--verde); color: var(--verde-tinta) !important; text-decoration: none; font-size: 15px; font-weight: 700; letter-spacing: .02em; cursor: pointer; }
  .boton.claro, button.claro { background: var(--caja); color: var(--texto) !important; border-color: var(--linea-2); }
  .boton.rojo, button.no { background: var(--rojo-fondo); color: var(--rojo) !important; border-color: transparent; }
  button:disabled { opacity: .5; cursor: progress; }
  .aviso { padding: 12px 16px; border-radius: 12px; background: var(--verde-fondo); color: var(--verde); font-weight: 700; margin: 0 0 14px; }
  .aviso.mal, .error { padding: 12px 16px; border-radius: 12px; background: var(--rojo-fondo); color: var(--rojo); font-weight: 700; margin: 0 0 14px; }
  .tareas { display: flex; flex-wrap: wrap; gap: 8px; margin: 0 0 14px; }
  .tareas a { padding: 9px 14px; border-radius: 10px; background: var(--amarillo-fondo); color: var(--amarillo); text-decoration: none; font-size: 14px; font-weight: 800; }
  .vacio, .nota { font-size: 13px; color: var(--flojo); }

  /* Formularios */
  form.op { display: grid; gap: 12px; }
  form.op fieldset { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 220px), 1fr)); gap: 12px 16px; margin: 0; padding: 18px; border: 1px solid var(--linea); border-radius: 16px; background: var(--caja); }
  form.op legend { float: left; width: 100%; padding: 0 0 2px; font-family: Carlito, Inter, sans-serif; font-weight: 700; font-size: 15px; letter-spacing: .08em; text-transform: uppercase; color: var(--suave); }
  form.op label { display: grid; gap: 6px; font-size: 13px; color: var(--suave); min-width: 0; }
  form.op small { color: var(--flojo); }
  input, select, textarea { font: inherit; }
  form.op input, form.op select, form.op textarea, .editar input, .editar select, .editar textarea, .acc textarea {
    width: 100%; padding: 11px 12px; border: 1px solid var(--linea-2); border-radius: 10px; background: var(--fondo-2); color: var(--texto); font-size: 16px; }
  form.op input:focus, form.op select:focus, form.op textarea:focus, input[type=search]:focus { outline: none; border-color: var(--verde); box-shadow: 0 0 0 3px var(--verde-fondo); }
  form.op .ancho { grid-column: 1 / -1; } form.op .acc { display: flex; gap: 10px; flex-wrap: wrap; }

  /* Historial */
  .hist { list-style: none; margin: 0; padding: 0; font-size: 14px; } .hist li { display: flex; gap: 12px; padding: 9px 0; border-bottom: 1px solid var(--linea); }
  .hist li:last-child { border-bottom: 0; } .hist time { flex: none; width: 122px; color: var(--flojo); font-size: 13px; }

  /* Móvil */
  @media (max-width: 700px) {
    html { font-size: 14px; }
    body { padding: 0 14px 90px; }
    .cabeza { margin: 0 -14px 2px; padding: calc(12px + env(safe-area-inset-top)) 14px 12px; }
    .cabeza__logo { height: 20px; }
    .tabla, .card .tabla { margin: 0 -14px; padding: 0 14px; }
    .card { padding: 16px 14px; border-radius: 14px; }
    .kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
    .kpi { padding: 13px 12px 12px; border-radius: 14px; }
    th:first-child, td:first-child { position: sticky; left: 0; z-index: 1; min-width: 170px; background: var(--caja); box-shadow: 1px 0 0 var(--linea); }
    .bars li { grid-template-columns: minmax(90px, 40%) 1fr auto; gap: 8px; }
    .hist li { flex-direction: column; gap: 2px; } .hist time { width: auto; }
    .barra .boton, .filtros .boton { flex: 1 1 auto; }
  }
`;

